package com.secure.documentwallet;

import org.json.JSONObject;
import java.text.DateFormatSymbols;
import java.time.DateTimeException;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.Locale;
import java.util.regex.*;

/** Extracts only explicitly labelled fields from on-device OCR text. */
final class DocumentDetailParser {
 private DocumentDetailParser(){}
 static JSONObject identity(String text,boolean front){JSONObject out=new JSONObject();try{out.put("issuer",front?"Driver's Permit":"National Identification Card");out.put("issueDate",date(text,"ISSUE\\s*DATE|DATE\\s*OF\\s*ISSUE|ISSUED(?:\\s*ON)?|VALID\\s*FROM"));out.put("expiryDate",date(text,"EXPIR(?:Y|ATION)\\s*DATE|DATE\\s*OF\\s*EXPIRY|EXPIRES|EXP\\.?\\s*DATE|VALID\\s*(?:UNTIL|TO)"));out.put("documentNumber",digitsAfter(text,front?"LICEN[CS]E":"REGISTRATION",front?"(?:#|NO\\.?|NUMBER)?":"(?:NO\\.?|NUMBER|#)?"));}catch(Exception ignored){}return out;}
 static JSONObject bank(String text,String issuer){JSONObject out=new JSONObject();try{out.put("issuer",issuer==null?"":issuer.trim());out.put("documentNumber",cardNumber(text));out.put("expiryDate",bankExpiry(text));}catch(Exception ignored){}return out;}
 private static String cardNumber(String text){Matcher candidates=Pattern.compile("(?<!\\d)(?<!\\d[ -])(\\d(?:[ -]?\\d){12,18})(?![ -]?\\d)").matcher(text==null?"":text.replace('\n',' ').replace('\r',' '));while(candidates.find()){String digits=candidates.group(1).replaceAll("\\D","");if(digits.length()>=13&&digits.length()<=19&&luhn(digits))return digits;}return "";}
 private static boolean luhn(String digits){int sum=0;boolean doubleDigit=false;for(int i=digits.length()-1;i>=0;i--){int value=digits.charAt(i)-'0';if(doubleDigit){value*=2;if(value>9)value-=9;}sum+=value;doubleDigit=!doubleDigit;}return sum%10==0;}
 private static String bankExpiry(String text){String value=flat(text);Matcher labelled=Pattern.compile("(?i)(?:(?:GOOD|VALID)\\s*THRU|VALID\\s*UNTIL|EXPIR(?:Y|ATION)(?:\\s*DATE)?|EXPIRES)\\s*[:#-]?\\s*(0?[1-9]|1[0-2])\\s*[/.-]\\s*(\\d{2}|\\d{4})").matcher(value);if(labelled.find())return bankDate(number(labelled,1),number(labelled,2));ArrayList<int[]> found=new ArrayList<>();Matcher monthYear=Pattern.compile("(?<![\\d/.-])(0?[1-9]|1[0-2])\\s*[/.-]\\s*(\\d{2}|\\d{4})(?![\\d/.-])").matcher(value);while(monthYear.find())found.add(new int[]{number(monthYear,1),year(number(monthYear,2))});if(!found.isEmpty())return bestBankDate(found);Matcher iso=Pattern.compile("\\b(\\d{4})\\s*[/.-]\\s*(\\d{1,2})\\s*[/.-]\\s*(\\d{1,2})\\b").matcher(value);while(iso.find())if(validDate(number(iso,3),number(iso,2),number(iso,1)))found.add(new int[]{number(iso,2),number(iso,1)});Matcher full=Pattern.compile("\\b(\\d{1,2})\\s*[/.-]\\s*(\\d{1,2})\\s*[/.-]\\s*(\\d{2,4})\\b").matcher(value);while(full.find()){int first=number(full,1),second=number(full,2),month=first<=12&&second>12?first:second,day=first<=12&&second>12?second:first,year=year(number(full,3));if(validDate(day,month,year))found.add(new int[]{month,year});}String names="JAN(?:UARY)?|FEB(?:RUARY)?|MAR(?:CH)?|APR(?:IL)?|MAY|JUN(?:E)?|JUL(?:Y)?|AUG(?:UST)?|SEP(?:TEMBER)?|SEPT|OCT(?:OBER)?|NOV(?:EMBER)?|DEC(?:EMBER)?";Matcher written=Pattern.compile("(?i)\\b("+names+")(?:[\\s,./-]+\\d{1,2}(?:st|nd|rd|th)?)?[\\s,./-]+(\\d{2,4})\\b").matcher(value);while(written.find())found.add(new int[]{month(written.group(1)),year(number(written,2))});Matcher writtenDayFirst=Pattern.compile("(?i)\\b\\d{1,2}(?:st|nd|rd|th)?[\\s,./-]+("+names+")[\\s,./-]+(\\d{2,4})\\b").matcher(value);while(writtenDayFirst.find())found.add(new int[]{month(writtenDayFirst.group(1)),year(number(writtenDayFirst,2))});return bestBankDate(found);}
 private static String bestBankDate(ArrayList<int[]> dates){if(dates.isEmpty())return "";YearMonth now=YearMonth.now();int best=-1,bestPast=-1;for(int[] date:dates){if(date[0]<1||date[0]>12)continue;int key=date[1]*12+date[0],current=now.getYear()*12+now.getMonthValue();if(key>=current)best=Math.max(best,key);else bestPast=Math.max(bestPast,key);}int selected=best>=0?best:bestPast;if(selected<0)return "";int year=(selected-1)/12,month=(selected-1)%12+1;return bankDate(month,year);}
 private static String bankDate(int month,int year){year=year(year);return month<1||month>12?"":new DateFormatSymbols(Locale.US).getMonths()[month-1]+"/"+year;}
 private static int year(int value){return value<100?value+(value<50?2000:1900):value;}
 private static boolean validDate(int day,int month,int year){try{LocalDate.of(year,month,day);return true;}catch(DateTimeException ignored){return false;}}
 private static String date(String text,String labels){String value=flat(text);Matcher label=Pattern.compile("(?i)(?:"+labels+")\\s*[:#-]?\\s*").matcher(value);if(!label.find())return "";String candidate=value.substring(label.end(),Math.min(value.length(),label.end()+48)).replaceAll("(?i)(\\d{1,2})(?:st|nd|rd|th)","$1");Matcher iso=Pattern.compile("\\b(\\d{4})\\s*[/.-]\\s*(\\d{1,2})\\s*[/.-]\\s*(\\d{1,2})\\b").matcher(candidate);if(iso.find())return normalized(number(iso,3),number(iso,2),number(iso,1));Matcher numeric=Pattern.compile("\\b(\\d{1,2})\\s*[/.-]\\s*(\\d{1,2})\\s*[/.-]\\s*(\\d{2,4})\\b").matcher(candidate);if(numeric.find()){int first=number(numeric,1),second=number(numeric,2);return first<=12&&second>12?normalized(second,first,number(numeric,3)):normalized(first,second,number(numeric,3));}String monthNames="JAN(?:UARY)?|FEB(?:RUARY)?|MAR(?:CH)?|APR(?:IL)?|MAY|JUN(?:E)?|JUL(?:Y)?|AUG(?:UST)?|SEP(?:TEMBER)?|SEPT|OCT(?:OBER)?|NOV(?:EMBER)?|DEC(?:EMBER)?";Matcher dayFirst=Pattern.compile("(?i)\\b(\\d{1,2})[\\s,./-]+("+monthNames+")[\\s,./-]+(\\d{2,4})\\b").matcher(candidate);if(dayFirst.find())return normalized(number(dayFirst,1),month(dayFirst.group(2)),number(dayFirst,3));Matcher monthFirst=Pattern.compile("(?i)\\b("+monthNames+")[\\s,./-]+(\\d{1,2})[\\s,./-]+(\\d{2,4})\\b").matcher(candidate);if(monthFirst.find())return normalized(number(monthFirst,2),month(monthFirst.group(1)),number(monthFirst,3));Matcher yearFirst=Pattern.compile("(?i)\\b(\\d{4})[\\s,./-]+("+monthNames+")[\\s,./-]+(\\d{1,2})\\b").matcher(candidate);if(yearFirst.find())return normalized(number(yearFirst,3),month(yearFirst.group(2)),number(yearFirst,1));Matcher compact=Pattern.compile("\\b(\\d{4})(\\d{2})(\\d{2})\\b").matcher(candidate);return compact.find()?normalized(number(compact,3),number(compact,2),number(compact,1)):"";}
 private static int number(Matcher matcher,int group){return Integer.parseInt(matcher.group(group));}
 private static String normalized(int day,int month,int year){year=year(year);try{LocalDate date=LocalDate.of(year,month,day);return String.format(Locale.US,"%02d/%02d/%04d",date.getDayOfMonth(),date.getMonthValue(),date.getYear());}catch(DateTimeException ignored){return "";}}
 private static int month(String value){String key=value.toUpperCase(Locale.US).replace("SEPT","SEP");for(int i=0;i<MONTHS.length;i++)if(key.startsWith(MONTHS[i]))return i+1;return 0;}
 private static final String[] MONTHS={"JAN","FEB","MAR","APR","MAY","JUN","JUL","AUG","SEP","OCT","NOV","DEC"};
 private static String digitsAfter(String text,String label,String suffix){Matcher m=Pattern.compile("(?i)"+label+"\\s*"+suffix+"\\s*[:#-]?\\s*([0-9][0-9\\s-]{2,24})").matcher(flat(text));return m.find()?m.group(1).replaceAll("\\D",""):"";}
 private static String flat(String text){return text==null?"":text.replace('\n',' ').replace('\r',' ').replaceAll("\\s+"," ");}
}
